cd /tmp/e5 && export DSTASK_GIT_REPO=/tmp/e5/r
t() { rm -rf /tmp/e5/r; mkdir -p /tmp/e5/r; git init -q /tmp/e5/r; r=$(/workspace/executable add "X" due:"$1" 2>&1); if echo "$r"|grep -q Invalid; then echo "$1 -> INVALID"; else echo "$1 -> $(grep -h '^due' /tmp/e5/r/pending/*.yml 2>/dev/null)"; fi }
for d in last-sunday last-saturday last-thursday last-wednesday last-tuesday next-sunday next-monday this-monday this-sunday; do t "$d"; done

